<?php require __DIR__.'/../includes/functions.php'; require_admin(); $leads=lead_rows(); $support=support_rows(); $traffic=traffic_rows(1500); $posts=load_posts(true); $content=json_encode(load_content(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE); ?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link href="https://cdn.jsdelivr.net/npm/quill@1.3.7/dist/quill.snow.css" rel="stylesheet"><link rel="stylesheet" href="../assets/styles.css?v=wysiwyg-blog-editor-20260824"></head><body class="admin-bg"><main class="admin-wrap"><div class="admin-head"><div><h1>Website Admin</h1><p>Manage enquiries, blog posts and website content.</p></div><div><a class="btn ghost" href="../index.php">View site</a><a class="btn ghost" href="../blog.php">View blog</a><a class="btn ghost" href="logout.php">Logout</a></div></div><?php if(!empty($_SESSION['flash'])): ?><div class="success-msg"><?=h($_SESSION['flash']); unset($_SESSION['flash']);?></div><?php endif; ?><section class="admin-card"><h2>Leads</h2><p>Total enquiries: <strong><?=count($leads)?></strong> <a href="export.php">Export CSV</a></p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Name</th><th>Phone</th><th>Email</th><th>Reply</th><th>Business</th><th>Service</th><th>Budget</th><th>Message</th></tr></thead><tbody><?php foreach(array_slice($leads,0,50) as $l): ?><tr><td><?=h($l['created_at']??'')?></td><td><?=h($l['name']??'')?></td><td><?=h($l['phone']??'')?></td><td><?=h($l['email']??'')?></td><td><a href="https://wa.me/<?=preg_replace('/\D/','',$l['phone']??'')?>" target="_blank" rel="noopener">WhatsApp</a><?php if(!empty($l['email'])): ?> · <a href="mailto:<?=h($l['email'])?>?subject=Lynxcom Analytics consultation request">Email</a><?php endif; ?></td><td><?=h($l['business']??'')?></td><td><?=h($l['service']??'')?></td><td><?=h($l['budget']??'')?></td><td><?=h($l['message']??'')?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="admin-card" id="traffic"><h2>Traffic tracker</h2><p>Total tracked visits: <strong><?=count($traffic)?></strong></p><div class="traffic-summary-grid"><div><h3>Top pages</h3><ul><?php foreach(traffic_summary($traffic,'page',8) as $k=>$v): ?><li><span><?=h($k)?></span><strong><?=h($v)?></strong></li><?php endforeach; ?></ul></div><div><h3>Referral sites</h3><ul><?php foreach(traffic_summary($traffic,'referrer_host',8) as $k=>$v): ?><li><span><?=h($k)?></span><strong><?=h($v)?></strong></li><?php endforeach; ?></ul></div><div><h3>Location/IP hints</h3><ul><?php foreach(traffic_summary($traffic,'location_hint',8) as $k=>$v): ?><li><span><?=h($k)?></span><strong><?=h($v)?></strong></li><?php endforeach; ?></ul></div><div><h3>UTM sources</h3><ul><?php foreach(traffic_summary($traffic,'utm_source',8) as $k=>$v): ?><li><span><?=h($k)?></span><strong><?=h($v)?></strong></li><?php endforeach; ?></ul></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Page</th><th>IP</th><th>Location hint</th><th>Referrer</th><th>UTM Source</th><th>Campaign</th><th>User agent</th></tr></thead><tbody><?php foreach(array_slice($traffic,0,120) as $v): ?><tr><td><?=h($v['created_at']??'')?></td><td><?=h($v['page']??'')?></td><td><?=h($v['ip']??'')?></td><td><?=h($v['location_hint']??'')?></td><td><?=h($v['referrer_host']??($v['referrer']??''))?></td><td><?=h($v['utm_source']??'')?></td><td><?=h($v['utm_campaign']??'')?></td><td><?=h(substr($v['user_agent']??'',0,120))?></td></tr><?php endforeach; ?></tbody></table></div><p><small>Note: location is an offline IP hint. For city/country accuracy later, we can add a GeoIP database or privacy-safe API.</small></p></section><section class="admin-card" id="support"><h2>Support tickets</h2><p>Total support requests: <strong><?=count($support)?></strong></p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Ticket</th><th>Name</th><th>Phone</th><th>Email</th><th>Category</th><th>Urgency</th><th>Subject</th><th>Message</th><th>Reply</th></tr></thead><tbody><?php foreach(array_slice($support,0,80) as $t): ?><tr><td><?=h($t['created_at']??'')?></td><td><?=h($t['ticket_id']??'')?></td><td><?=h($t['name']??'')?></td><td><?=h($t['phone']??'')?></td><td><?=h($t['email']??'')?></td><td><?=h($t['category']??'')?></td><td><?=h($t['urgency']??'')?></td><td><?=h($t['subject']??'')?></td><td><?=h($t['message']??'')?></td><td><a href="https://wa.me/<?=preg_replace('/\D/','',$t['phone']??'')?>" target="_blank" rel="noopener">WhatsApp</a><?php if(!empty($t['email'])): ?> · <a href="mailto:<?=h($t['email'])?>?subject=Re: <?=h($t['subject']??'Lynxcom support')?>">Email</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="admin-card" id="blog"><h2>Blog posts</h2><p>Create helpful articles that answer real business questions and attract free Google search traffic.</p><form class="blog-admin-form rich-post-form" method="post" action="save-blog.php"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value=""><div class="form-row"><input name="title" placeholder="Post title" required><input name="slug" placeholder="URL slug — leave blank to auto-generate"></div><div class="form-row"><input name="cover_image" placeholder="Cover image path or URL e.g. assets/section-services.jpg"><input name="cover_alt" placeholder="Cover image description"></div><textarea name="summary" placeholder="Short summary for Google and blog cards"></textarea><div class="wysiwyg-editor" data-placeholder="Write the full blog post here. Format text visually and insert links/images."></div><textarea class="hidden-html" name="content_html"></textarea><textarea class="plain-content" name="content" placeholder="Plain text fallback — optional"></textarea><div class="form-row"><input name="keywords" placeholder="Internal keywords/topics — optional"><select name="status"><option value="published">Published</option><option value="draft">Draft</option></select></div><button class="btn primary">Publish blog post</button></form><div class="admin-post-list"><h3>Existing posts</h3><?php foreach($posts as $p): ?><article><div><strong><?=h($p['title']??'Untitled')?></strong><span><?=h($p['status']??'published')?> · <?=h($p['created_at']??'')?></span><a href="../post.php?slug=<?=urlencode($p['slug']??'')?>" target="_blank" rel="noopener">View</a></div><details><summary>Edit this post</summary><form method="post" action="save-blog.php" class="rich-post-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($p['id']??'')?>"><input name="title" value="<?=h($p['title']??'')?>" required><input name="slug" value="<?=h($p['slug']??'')?>"><div class="form-row"><input name="cover_image" value="<?=h($p['cover_image']??'')?>" placeholder="Cover image path or URL"><input name="cover_alt" value="<?=h($p['cover_alt']??'')?>" placeholder="Cover image description"></div><textarea name="summary"><?=h($p['summary']??'')?></textarea><div class="wysiwyg-editor"><?=clean_html($p['content_html']??'')?></div><textarea class="hidden-html" name="content_html"></textarea><textarea class="plain-content" name="content"><?=h($p['content']??'')?></textarea><div class="form-row"><input name="keywords" value="<?=h($p['keywords']??'')?>"><select name="status"><option value="published" <?=($p['status']??'published')==='published'?'selected':''?>>Published</option><option value="draft" <?=($p['status']??'')==='draft'?'selected':''?>>Draft</option></select></div><button class="btn primary">Save changes</button><button class="btn ghost" name="action" value="delete" onclick="return confirm('Delete this blog post?')">Delete</button></form></details></article><?php endforeach; ?></div></section><section class="admin-card" id="content"><h2>Edit website content</h2><p>Edit carefully. This is JSON. Invalid JSON will not save.</p><form method="post" action="save-content.php"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><textarea class="json-editor" name="content_json"><?=h($content)?></textarea><button class="btn primary">Save content</button></form></section></main><script src="https://cdn.jsdelivr.net/npm/quill@1.3.7/dist/quill.min.js"></script><script src="../assets/admin-blog-editor.js?v=wysiwyg-blog-editor-20260824"></script></body></html>